const themePalettes:Record<ThemeName,Record<string,string>>={light:{bg:'#ffffff',ink:'#17191d',muted:'#9298a1',blue:'#3478f6',green:'#35c56a',line:'#edf0f4',soft:'#f5f6f9',white:'#fff',surface:'#ffffff',surfaceAlt:'#f2f4f7',button:'#17181b',buttonText:'#fff'},dark:{bg:'#0c1016',ink:'#f3f5f8',muted:'#9da8b5',blue:'#78aaff',green:'#48d28a',line:'#28313d',soft:'#1b232e',white:'#ffffff',surface:'#151c25',surfaceAlt:'#202a36',button:'#e9eef5',buttonText:'#111820'},cyberpunk:{bg:'#f5dc42',ink:'#0754bd',muted:'#315f9e',blue:'#005bdb',green:'#1b805a',line:'#d2b927',soft:'#f1d443',white:'#fffdf0',surface:'#fff1a1',surfaceAlt:'#f7df57',button:'#0754bd',buttonText:'#ffe957'}};
let currentTheme:ThemeName='light';
function themeColor(value:string,kind:'text'|'background'|'border'='text'){const hex=value.toLowerCase();const palette=themePalettes[currentTheme];if(currentTheme==='light')return value;if(kind==='text'){if(['#17191d','#17181b','#252a30','#252a2f','#28313a','#33363a'].includes(hex))return palette.ink;if(['#9298a1','#9299a2','#8d949d','#9aa1aa','#9aa0a7','#8e949c','#8e959e','#989ea6','#9199a3','#9ba2aa','#69727c','#707984','#7e8791','#444c55','#8f969e','#9ca2aa','#7f8790','#77808a','#84919c','#7a838c','#596875','#687682','#7c848e','#5f6871','#535b63','#647487'].includes(hex))return palette.muted;if(['#3478f6','#005bdb'].includes(hex))return palette.blue;return value;}if(kind==='border')return ['#edf0f3','#edf0f4','#e0e6eb','#eef0f3','#d8e5f3','#c6cbd2'].includes(hex)?palette.line:value;if(['#fff','#ffffff','#fffdf0'].includes(hex))return palette.surface;if(['#17191d','#17181b'].includes(hex))return palette.button;if(['#f2f4f7','#f2f5f8','#f3f5f7','#f5f6f9','#f7f8fa','#f1f4f7','#f1f2f5','#f2f3f5','#eff0f3','#edf0f4','#edf0f3','#e8ebef','#f6f7f9','#f3f4f6','#f0f1f3','#f5f8fb','#f6f8fa','#f8f9fa','#f4f6f8','#eef1f5'].includes(hex))return palette.surfaceAlt;if(hex==='#d8f0fc')return currentTheme==='cyberpunk'?'#efcf28':'#1b3346';if(hex==='#3478f6')return palette.blue;return value;}
