function LoadingScreen(){
 const pulseA=useRef(new Animated.Value(.35)).current;
 const pulseB=useRef(new Animated.Value(.35)).current;
 const pulseC=useRef(new Animated.Value(.35)).current;
 useEffect(()=>{
  const pulse=(value:Animated.Value,delay:number)=>Animated.loop(Animated.sequence([
   Animated.delay(delay),
   Animated.timing(value,{toValue:1,duration:420,useNativeDriver:true}),
   Animated.timing(value,{toValue:.35,duration:420,useNativeDriver:true}),
   Animated.delay(520-delay),
  ]));
  const animations=[pulse(pulseA,0),pulse(pulseB,170),pulse(pulseC,340)];
  animations.forEach(animation=>animation.start());
  return()=>animations.forEach(animation=>animation.stop());
 },[pulseA,pulseB,pulseC]);
 return <SafeAreaView style={{flex:1,backgroundColor:'#fff',alignItems:'center',justifyContent:'center'}}>
  <View style={{alignItems:'center',justifyContent:'center',padding:36}}>
   <View style={{width:116,height:116,borderRadius:38,backgroundColor:'#edf6ff',alignItems:'center',justifyContent:'center',marginBottom:28}}>
    <Svg width={58} height={58} viewBox="0 0 48 48"><Path d="M8 18v12M14 14v20M34 14v20M40 18v12M14 24h20" stroke="#3478f6" strokeWidth={4} strokeLinecap="round"/><Circle cx="24" cy="24" r="3.5" fill="#55b9ed"/></Svg>
   </View>
   <Text style={{fontSize:25,fontWeight:'800',letterSpacing:-.5,color:'#17191d'}}>Repday</Text>
   <Text style={{fontSize:16,fontWeight:'500',color:'#7f8b98',marginTop:7}}>Getting your training ready</Text>
   <View style={{height:38,flexDirection:'row',alignItems:'center',gap:9,marginTop:24}}>
    {[pulseA,pulseB,pulseC].map((value,index)=><Animated.View key={index} style={{width:10,height:10,borderRadius:5,backgroundColor:['#3478f6','#55b9ed','#35c56a'][index],opacity:value,transform:[{scale:value}]}}/>)}
   </View>
  </View>
 </SafeAreaView>;
}

function WorkoutConfetti(){
 const colors=['#3478f6','#55b9ed','#35c56a','#ff9f43','#ff6b7a','#9b7bff'];
 const particles=useMemo(()=>Array.from({length:30},(_,index)=>({left:`${(index*37+9)%96}%` as `${number}%`,width:index%4===0?9:7,height:index%4===0?9:12,color:colors[index%colors.length],round:index%3===0,duration:1350+(index%7)*95,delay:(index%10)*42,drift:((index*19)%100)-50})),[]);
 const progress=useRef(particles.map(()=>new Animated.Value(0))).current;
 useEffect(()=>{const animations=progress.map((value,index)=>Animated.timing(value,{toValue:1,duration:particles[index].duration,delay:particles[index].delay,useNativeDriver:true}));Animated.parallel(animations).start();return()=>animations.forEach(animation=>animation.stop());},[particles,progress]);
 return <View pointerEvents="none" style={{position:'absolute',top:0,left:0,right:0,bottom:0,zIndex:20,overflow:'hidden'}}>{particles.map((particle,index)=>{const value=progress[index];return <Animated.View key={index} style={{position:'absolute',left:particle.left,top:-16,width:particle.width,height:particle.height,borderRadius:particle.round?6:2,backgroundColor:particle.color,opacity:value.interpolate({inputRange:[0,.08,.72,1],outputRange:[0,1,1,0]}),transform:[{translateY:value.interpolate({inputRange:[0,1],outputRange:[0,Dimensions.get('window').height*.9]})},{translateX:value.interpolate({inputRange:[0,1],outputRange:[0,particle.drift]})},{rotate:value.interpolate({inputRange:[0,1],outputRange:['0deg',`${(index%2?1:-1)*(480+(index%4)*180)}deg`]})}]}}/>;})}</View>;
}

