 const analyzeNote=async()=>{const catalog=await getImportCatalog();const parsed=parseWorkoutNote(noteText,catalog);if(!parsed.length){setImportError('I couldn’t find exercises yet. Try including names with sets and reps, like “Bench Press — 3 x 8 at 40 kg.”');setImportDrafts([]);return;}const stamp=Date.now();setImportError('');const drafts=parsed.map((split,index)=>({id:`note-${stamp}-${index}`,name:split.name,description:'Imported from Apple Notes',accent:'#edf4fc',moves:split.moves.map((move,moveIndex)=>{const exercise=findCatalogExercise(move.name,catalog);return{key:`note-${stamp}-${index}-${moveIndex}`,name:exercise?.name??move.name,image:exercise?.image,gif_url:exercise?.gif_url,target:exercise?.target,equipment:exercise?.equipment,instructions:exercise?.instructions,instruction_steps:exercise?.instruction_steps,restSeconds:'90',sets:Array.from({length:move.sets},()=>({weight:String(move.weight),reps:String(move.reps),done:false}))};})}));cacheImportedMedia(drafts);setImportDrafts(drafts);};
 const analyzeNoteWithAI=async()=>{if(!noteText.trim()||aiImporting)return;setAiImporting(true);setImportError('');setImportDrafts([]);try{const catalogPromise=getImportCatalog();const host=Constants.expoConfig?.hostUri?.split(':')[0];const base=Platform.OS==='web'?'':process.env.EXPO_PUBLIC_API_URL?.replace(/\/$/,'')||(host?`http://${host}:8081`:'');if(Platform.OS!=='web'&&!base)throw new Error('Can’t reach the AI service. Configure EXPO_PUBLIC_API_URL and try again.');const response=await fetch(`${base}/api/analyze-workout`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:noteText})});const responseText=await response.text();let result:any;try{result=JSON.parse(responseText);}catch{const trimmed=responseText.trimStart();const isHtml=trimmed.startsWith('<!DOCTYPE')||trimmed.startsWith('<html');throw new Error(isHtml?'The AI endpoint returned a web page instead of data. Restart the Expo server and try again.':'The AI service returned an unreadable response. Please try again.');}if(!response.ok)throw new Error(result.error||'AI analysis is temporarily unavailable.');if(!Array.isArray(result.splits)||!result.splits.length)throw new Error('No workout splits were found in that note.');const catalog=await catalogPromise;const stamp=Date.now();const drafts:Session[]=result.splits.map((split:any,index:number)=>({id:`ai-note-${stamp}-${index}`,name:String(split.name||`Workout ${index+1}`),description:'Imported from Apple Notes',accent:'#edf4fc',moves:(Array.isArray(split.exercises)?split.exercises:[]).map((exercise:any,moveIndex:number)=>{const known=findCatalogExercise(String(exercise.name),catalog);const prescriptions=Array.isArray(exercise.sets)?exercise.sets:[];return{key:`ai-note-${stamp}-${index}-${moveIndex}`,name:known?.name??String(exercise.name),image:known?.image,gif_url:known?.gif_url,target:known?.target,equipment:known?.equipment,instructions:known?.instructions,instruction_steps:known?.instruction_steps,restSeconds:'90',sets:prescriptions.map((set:any)=>({weight:String(set.weight??0),reps:String(set.reps??8),done:false}))};}).filter((move:Move)=>move.sets.length>0)})).filter((split:Session)=>split.moves.length>0);if(!drafts.length)throw new Error('No complete exercise prescriptions were found. Try local analysis or add sets and reps.');cacheImportedMedia(drafts);setImportDrafts(drafts);}catch(error){setImportError(error instanceof Error?error.message:'AI analysis is temporarily unavailable. You can still use local analysis.');}finally{setAiImporting(false);}};
 const saveImportedSplits=()=>{if(!importDrafts.length)return;cacheImportedMedia(importDrafts);const next=addCatalogMedia([...importDrafts,...sessions],catalogRef.current);setSessions(next);if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)syncSplitsCloud({items:withoutSampleSplits(next)}).catch(()=>{});setSelected(importDrafts[0].id);setImportDrafts([]);setNoteText('');setModal(null);incomingShare.clearSharedPayloads();notifyToast(`${importDrafts.length} split${importDrafts.length===1?'':'s'} added`);};
 const setPlanForDay=(day:number,sessionId:string|null)=>{setWeeklyPlan(current=>({...current,[day]:sessionId}));if(day===currentDayIndex&&sessionId)setSelected(sessionId);setPlanDay(null);setPendingPlanChange(null);setModal(null);notifyToast(sessionId?'Workout added to weekly plan':'Rest day saved');};const requestPlanChange=(day:number,sessionId:string|null)=>{if(Object.prototype.hasOwnProperty.call(weeklyPlan,day)&&weeklyPlan[day]===sessionId){setPlanDay(null);setModal(null);return;}setPendingPlanChange({day,sessionId});};
 const deleteSession=(id:string)=>{const remaining=sessions.filter(item=>item.id!==id);if(focusDraft?.session.id===id)setFocusDraft(null);setSessions(remaining);if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId&&!sampleSplitIds.has(id)){const clientIds=remaining.filter(item=>!sampleSplitIds.has(item.id)).map(item=>item.id);deleteSplitCloud({clientId:id}).then(()=>reorderSplitPositionsCloud({clientIds})).catch(()=>{});}setWeeklyPlan(plan=>Object.fromEntries(Object.entries(plan).filter(([,plannedId])=>plannedId!==id)) as Record<number,string|null>);if(selected===id)setSelected(remaining[0]?.id??'');setConfirmDelete(false);setModal(editReturn==='splits'?'splits':null);notifyToast('Split deleted');};
 const seconds=activeWorkout?Math.max(0,Math.floor(((activeWorkout.pausedAt??now)-activeWorkout.startedAt-activeWorkout.pausedMs)/1000)):0; const paused=!!activeWorkout?.pausedAt; const restSeconds=restEndsAt?Math.max(0,Math.ceil((restEndsAt-now)/1000)):0;
 const start=(plannedSession?:Session)=>{if(!plannedSession&&!session)return;if(activeWorkout&&working){setModal('workout');return;}const fresh=JSON.parse(JSON.stringify(plannedSession??session)) as Session;fresh.moves=fresh.moves.map(m=>({...m,sets:m.sets.map(s=>({...s,done:false}))}));setWorking(fresh);setActiveWorkout({startedAt:Date.now(),pausedAt:null,pausedMs:0});setRestEndsAt(null);setModal('workout');requestWorkoutNotificationPermission().then((permission:any)=>setNotificationsReady(!!permission?.granted)).catch(()=>{});};
 const addSession=()=>{const name=draftName.trim();if(!name)return;const item:Session={id:Date.now().toString(),name,description:draftDesc.trim()||'Your custom workout',accent:'#e6edff',moves:[]};setSessions(a=>[...a,item]);if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)upsertSplitCloud({item,position:sessions.filter(entry=>!sampleSplitIds.has(entry.id)).length}).catch(()=>{});setSelected(item.id);setDraftName('');setDraftDesc('');setModal(null);notifyToast('Split added');};
 const addExercise=(e:Exercise)=>{if(!editorSession)return;const movement:Move={key:`${e.id}-${Date.now()}`,name:e.name,restSeconds:'90',image:e.image,gif_url:e.gif_url,target:e.target,equipment:e.equipment,instructions:e.instructions,instruction_steps:e.instruction_steps,sets:[{weight:'0',reps:'10',done:false},{weight:'0',reps:'10',done:false},{weight:'0',reps:'10',done:false}]};patchEditorSession(s=>({...s,moves:[...s.moves,movement]}));setModal(null);setQuery('');notifyToast('Exercise added');};
