 const saveExerciseDraft=()=>{if(!editorSession||!exerciseDraft||!exerciseDraft.name.trim())return;const saved:Move={...exerciseDraft,name:exerciseDraft.name.trim(),image:exerciseDraft.image?.trim()||undefined,gif_url:exerciseDraft.gif_url?.trim()||undefined,target:exerciseDraft.target?.trim()||undefined,equipment:exerciseDraft.equipment?.trim()||undefined,instructions:exerciseDraft.instructions?.en?.trim()?{en:exerciseDraft.instructions.en.trim()}:undefined,instruction_steps:exerciseDraft.instruction_steps?.en?.length?exerciseDraft.instruction_steps:undefined,restSeconds:exerciseDraft.restSeconds?.trim()||'90'};patchEditorSession(current=>({...current,moves:current.moves.map(move=>move.key===saved.key?saved:move)}));cacheExerciseMedia([saved]);setExerciseDraft(null);setModal('edit');};
 const showExercise=(move:Move,returnTo:'edit'|'workout',inDrawer=false)=>{const known=findCatalogExercise(move.name,exerciseLibrary);setPreviewMedia('animation');setPreviewLanguage('en');setLanguageMenuOpen(false);setPreviewExercise({...known,id:known?.id??move.key,name:move.name,category:known?.category??'',target:known?.target??move.target??'',equipment:known?.equipment??move.equipment??'',media_id:known?.media_id??'',image:move.image??known?.image,gif_url:move.gif_url??known?.gif_url,instructions:move.instructions??known?.instructions,instruction_steps:move.instruction_steps??known?.instruction_steps});setPreviewReturn(returnTo);setAnimationMissing(false);setDrawerPreviewOpen(inDrawer);if(inDrawer){drawerPreviewOpacity.setValue(0);drawerPreviewTranslateY.setValue(12);requestAnimationFrame(()=>Animated.parallel([Animated.timing(drawerPreviewOpacity,{toValue:1,duration:220,useNativeDriver:true}),Animated.spring(drawerPreviewTranslateY,{toValue:0,useNativeDriver:true,damping:24,stiffness:260})]).start());}else setModal('exercise');};
 useEffect(()=>{if((modal!=='exercise'&&!drawerPreviewOpen)||!previewExercise||previewExercise.gif_url)return;let cancelled=false;setAnimationLoading(true);fetch('https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/data/exercises.json').then(response=>{if(!response.ok)throw new Error('Exercise media unavailable');return response.json();}).then((data:unknown)=>{if(cancelled||!Array.isArray(data))return;const item=data.find(row=>row&&typeof row.name==='string'&&row.name.toLowerCase()===previewExercise.name.toLowerCase());if(!item){setAnimationMissing(true);return;}setPreviewExercise(current=>current?({...current,gif_url:typeof item.gif_url==='string'?item.gif_url:undefined,target:String(item.target??current.target),equipment:String(item.equipment??current.equipment),instructions:item.instructions,instruction_steps:item.instruction_steps}):current);if(typeof item.gif_url!=='string')setAnimationMissing(true);}).catch(()=>{if(!cancelled)setAnimationMissing(true);}).finally(()=>{if(!cancelled)setAnimationLoading(false);});return()=>{cancelled=true;};},[modal,drawerPreviewOpen,previewExercise?.name,previewExercise?.gif_url]);
 const updateSet=(mi:number,si:number,field:keyof SetEntry,value:string|boolean)=>{const nextWorking=working?({...working,moves:working.moves.map((m,i)=>i!==mi?m:{...m,sets:m.sets.map((s,j)=>j===si?{...s,[field]:value}:s)})}):null;if(nextWorking)setWorking(nextWorking);if((field==='done'||field==='weight'||field==='reps')&&activeWorkout&&isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)updateActiveWorkoutSetCloud({sessionKey:String(activeWorkout.startedAt),moveIndex:mi,setIndex:si,field,value:value as string|boolean}).catch(()=>{});if(field==='done'&&value===true){const duration=Math.max(0,Number(working?.moves[mi]?.restSeconds??90)||0);const next=Date.now()+duration*1000;setRestDurationSeconds(duration);setRestEndsAt(duration>0?next:null);if(restNotification.current)Notifications.cancelScheduledNotificationAsync(restNotification.current).catch(()=>{});restNotification.current=null;if(duration>0)Notifications.scheduleNotificationAsync({content:{title:'Rest complete',body:'Time for your next set.'},trigger:{type:Notifications.SchedulableTriggerInputTypes.DATE,date:next}}).then(id=>restNotification.current=id).catch(()=>{});}}
 const addWorkingSet=(mi:number)=>{if(!working)return;const move=working.moves[mi];const last=move.sets.at(-1);const nextSet={weight:last?.weight??'0',reps:last?.reps??'10',done:false};setWorking({...working,moves:working.moves.map((item,index)=>index===mi?{...item,sets:[...item.sets,nextSet]}:item)});if(activeWorkout&&isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)addActiveWorkoutSetCloud({sessionKey:String(activeWorkout.startedAt),moveIndex:mi,setIndex:move.sets.length,weight:nextSet.weight,reps:nextSet.reps}).catch(()=>{});notifyToast('Set added');};
 const togglePause=()=>setActiveWorkout(a=>{if(!a)return a;const at=Date.now();return a.pausedAt?{...a,pausedMs:a.pausedMs+at-a.pausedAt,pausedAt:null}:{...a,pausedAt:at};});
 const discardWorkout=()=>{stopWorkoutSurface();if(restNotification.current)Notifications.cancelScheduledNotificationAsync(restNotification.current).catch(()=>{});restNotification.current=null;setActiveWorkout(null);setWorking(null);setRestEndsAt(null);setConfirmDiscardWorkout(false);setModal(null);notifyToast('Workout discarded');};
 const confirmDeleteHistoryRecord=async()=>{if(!historyDeleteTarget||historyDeleteStatus==='deleting'||historyDeleteStatus==='deleted')return;const deletedId=historyDeleteTarget.id;setHistoryDeleteStatus('deleting');setHistoryDeleteError('');try{if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)await deleteHistoryCloud({clientId:deletedId});deletedHistoryIdsRef.current.add(deletedId);setHistory(current=>current.filter(record=>record.id!==deletedId));setHistoryDeleteStatus('deleted');notifyToast('Workout deleted');setTimeout(()=>{setHistoryDeleteTarget(current=>current?.id===deletedId?null:current);setHistoryDeleteStatus('confirm');},900);}catch{setHistoryDeleteStatus('confirm');setHistoryDeleteError('Could not delete this saved workout. Try again.');}};
 const finish=()=>{const completedAt=Date.now();setSummarySeconds(seconds);setSummaryCompletedAt(completedAt);setConfettiKey(key=>key+1);if(working){const record:WorkoutRecord={id:String(completedAt),name:working.name,startedAt:activeWorkout?.startedAt??completedAt-seconds*1000,duration:seconds,volume:working.moves.reduce((n,m)=>n+m.sets.filter(s=>s.done).reduce((a,s)=>a+(Number(s.weight)||0)*(Number(s.reps)||0),0),0),sets:working.moves.reduce((n,m)=>n+m.sets.filter(s=>s.done).length,0),exercises:working.moves.filter(m=>m.sets.some(s=>s.done)).length,session:working};setHistory(h=>[record,...h]);if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)upsertHistoryItemCloud({item:record}).catch(()=>{});}setFocusDraft(null);stopWorkoutSurface();if(restNotification.current)Notifications.cancelScheduledNotificationAsync(restNotification.current).catch(()=>{});setActiveWorkout(null);setRestEndsAt(null);setStreak(n=>n+1);setModal('summary');setConfirmFinishWorkout(false);notifyToast('Workout saved');}; const requestFinishWorkout=()=>{if(activeCompleted===0)return;if(activeIncomplete>0)setConfirmFinishWorkout(true);else finish();};
 const shareCompletedWorkout=async()=>{if(!summaryCaptureRef.current||sharingSummary)return;setSharingSummary(true);try{await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));const uri=await captureRef(summaryCaptureRef.current,{format:'png',quality:1,result:Platform.OS==='web'?'data-uri':'tmpfile'});if(Platform.OS==='web'){const blob=await(await fetch(uri)).blob();const file=new File([blob],'repday-workout.png',{type:'image/png'});const shareNavigator=navigator as Navigator&{canShare?:(data:ShareData)=>boolean};if(typeof shareNavigator.share==='function'&&shareNavigator.canShare?.({files:[file]})){await shareNavigator.share({files:[file],title:`${working?.name??'Workout'} complete`,text:'Workout summary'});}else{const link=document.createElement('a');link.href=uri;link.download='repday-workout.png';link.click();notifyToast('Workout image downloaded and ready to share');}}else if(await Sharing.isAvailableAsync()){await Sharing.shareAsync(uri,{mimeType:'image/png',dialogTitle:'Share workout'});}else notifyToast('Sharing is unavailable on this device');}catch(error){if(!(error instanceof Error&&error.name==='AbortError'))notifyToast('Could not create the workout image');}finally{setSharingSummary(false);}};
 const time=formatTime(modal==='summary'?summarySeconds:seconds);
 const toggleActivityView=()=>{if(!activityExpanded)setActivityMonth(new Date());setActivityExpanded(expanded=>!expanded);}; const toggleActivityCollapsed=()=>setActivityCollapsed(value=>!value);

 const sendCoachQuestion=async(question=coachInput)=>{const value=question.trim();if(!value||coachBusy)return;setCoachMessages(current=>[...current,{role:'user',text:value}]);setCoachInput('');setCoachError('');setCoachBusy(true);try{const host=Constants.expoConfig?.hostUri?.split(':')[0];const base=Platform.OS==='web'?'':process.env.EXPO_PUBLIC_API_URL?.replace(/\/$/,'')||(host?`http://${host}:8081`:'');if(Platform.OS!=='web'&&!base)throw new Error('Can’t reach AI Coach. Configure EXPO_PUBLIC_API_URL and try again.');const context=[focusPlan?`Today’s split: ${focusPlan.name}; exercises: ${focusPlan.moves.map(move=>move.name).join(', ')}.`:'No split planned today.',...history.slice(0,5).map(record=>`${record.name}: ${record.sets} sets, ${Math.round(record.volume)} kg volume, ${formatTime(record.duration)} on ${new Date(record.startedAt).toLocaleDateString()}.`)].join('\n');const response=await fetch(`${base}/api/coach`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:value,context})});const raw=await response.text();let payload:any;try{payload=JSON.parse(raw);}catch{throw new Error('AI Coach returned an unreadable response. Try again.');}if(!response.ok)throw new Error(payload.error||'AI Coach is temporarily unavailable.');setCoachMessages(current=>[...current,{role:'assistant',text:String(payload.answer||'I couldn’t prepare a response. Please try again.')}]);}catch(error){setCoachError(error instanceof Error?error.message:'AI Coach is temporarily unavailable.');}finally{setCoachBusy(false);}};
