function ActivityTracker({collapsed,onCollapseToggle,expanded,month,onToggle,onMonthChange,history,weeklyPlan,weekStart,now,timeZone,sessions,scheduledCount,todaysPlan,onStart,onEdit,onPlanDay}:{collapsed:boolean;onCollapseToggle:()=>void;expanded:boolean;month:Date;onToggle:()=>void;onMonthChange:(amount:number)=>void;history:WorkoutRecord[];weeklyPlan:Record<number,string|null>;weekStart:number;now:number;timeZone:string;sessions:Session[];scheduledCount:number;todaysPlan?:Session;onStart:()=>void;onEdit:()=>void;onPlanDay:(weekday:number)=>void}){
 const viewProgress=useRef(new Animated.Value(expanded?1:0)).current;
 useEffect(()=>{const animation=Animated.timing(viewProgress,{toValue:expanded?1:0,duration:420,easing:Easing.inOut(Easing.cubic),useNativeDriver:false});animation.start();return()=>animation.stop();},[expanded,viewProgress]);
 const contentHeight=useRef(new Animated.Value(collapsed?0:expanded?455:190)).current;
 const collapseProgress=useRef(new Animated.Value(collapsed?1:0)).current;
 const calendarButtonProgress=useRef(new Animated.Value(collapsed?0:1)).current;
 useEffect(()=>{const animation=Animated.timing(contentHeight,{toValue:collapsed?0:expanded?455:190,duration:360,easing:Easing.inOut(Easing.cubic),useNativeDriver:false});animation.start();return()=>animation.stop();},[collapsed,expanded,contentHeight]);
 useEffect(()=>{const animation=Animated.timing(collapseProgress,{toValue:collapsed?1:0,duration:300,easing:Easing.inOut(Easing.cubic),useNativeDriver:false});animation.start();return()=>animation.stop();},[collapsed,collapseProgress]);
 useEffect(()=>{const animation=Animated.timing(calendarButtonProgress,{toValue:collapsed?0:1,duration:300,easing:Easing.out(Easing.cubic),useNativeDriver:false});animation.start();return()=>animation.stop();},[collapsed,calendarButtonProgress]);
 const cardPadding=collapseProgress.interpolate({inputRange:[0,1],outputRange:[19,12],extrapolate:'clamp'});
 const calendarButtonWidth=calendarButtonProgress.interpolate({inputRange:[0,1],outputRange:[0,42],extrapolate:'clamp'});
 const calendarButtonOpacity=calendarButtonProgress.interpolate({inputRange:[0,.35,1],outputRange:[0,0,1],extrapolate:'clamp'});
 const calendarButtonScale=calendarButtonProgress.interpolate({inputRange:[0,1],outputRange:[.75,1],extrapolate:'clamp'});
 const chartHeight=viewProgress.interpolate({inputRange:[0,1],outputRange:[190,0],extrapolate:'clamp'});
 const calendarHeight=viewProgress.interpolate({inputRange:[0,1],outputRange:[0,455],extrapolate:'clamp'});
 const chartOpacity=viewProgress.interpolate({inputRange:[0,.35,.72,1],outputRange:[1,1,0,0],extrapolate:'clamp'});
 const calendarOpacity=viewProgress.interpolate({inputRange:[0,.3,.68,1],outputRange:[0,0,1,1],extrapolate:'clamp'});
 const arrowRotation=viewProgress.interpolate({inputRange:[0,1],outputRange:['0deg','180deg']});
 const weekMinutes=useMemo(()=>Array.from({length:7},(_,index)=>{const day=new Date(weekStart);day.setDate(day.getDate()+index);return history.filter(workout=>new Date(workout.startedAt).toDateString()===day.toDateString()).reduce((total,workout)=>total+Math.max(0,workout.duration)/60,0);}),[history,weekStart]);
 const weeklyCount=weekMinutes.filter(minutes=>minutes>0).length;
 const totalMinutes=Math.round(weekMinutes.reduce((total,minutes)=>total+minutes,0));
 const maxMinutes=Math.max(60,...weekMinutes);
 const monthCells=useMemo(()=>{const first=new Date(month.getFullYear(),month.getMonth(),1);const offset=first.getDay();const count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const historyDays=new Set(history.map(workout=>new Date(workout.startedAt).toDateString()));const todayKey=new Date(now).toDateString();return Array.from({length:42},(_,index)=>{const dayNumber=index-offset+1;if(dayNumber<1||dayNumber>count)return null;const date=new Date(month.getFullYear(),month.getMonth(),dayNumber);const weekday=(date.getDay()+6)%7;return{dayNumber,key:date.toDateString(),weekday,done:historyDays.has(date.toDateString()),rest:Object.prototype.hasOwnProperty.call(weeklyPlan,weekday)&&weeklyPlan[weekday]===null,today:date.toDateString()===todayKey};});},[history,month,now,weeklyPlan]);
 const hours=Math.floor(totalMinutes/60);const minutes=totalMinutes%60;const durationLabel=hours?`${hours}h ${minutes}m`:`${totalMinutes} min`;
 const planLabel=(weekday:number)=>{if(!Object.prototype.hasOwnProperty.call(weeklyPlan,weekday))return'Plan';if(weeklyPlan[weekday]===null)return'Rest';return sessions.find(session=>session.id===weeklyPlan[weekday])?.name.split(' ')[0]??'Plan';};
 return <Animated.View style={[styles.activityCard,{paddingVertical:cardPadding}]}>
  <View style={styles.activityHeader}><View style={{flex:1}}><Text style={styles.activityTitle}>Weekly activity</Text><Text style={[styles.activitySummary,{fontWeight:'800'}]}>{scheduledCount} planned {scheduledCount===1?'day':'days'}{weeklyCount?` · ${durationLabel}`:''}</Text><Text style={styles.activityClock}>{formatClock(now,timeZone)} · {formatShortDate(now,timeZone)}</Text></View><View style={{flexDirection:'row',alignItems:'center',gap:6}}><Animated.View pointerEvents={collapsed?'none':'auto'} style={{width:calendarButtonWidth,opacity:calendarButtonOpacity,transform:[{scale:calendarButtonScale}],overflow:'hidden'}}><Pressable accessibilityRole="button" accessibilityState={{expanded}} accessibilityLabel={expanded?'Show weekly chart':'Show monthly calendar'} onPress={onToggle} style={styles.activityToggle}><Icon name="calendar" color={themeColor('#17191d')} size={20}/></Pressable></Animated.View><Pressable accessibilityRole="button" accessibilityState={{expanded:!collapsed}} accessibilityLabel={collapsed?'Expand weekly activity':'Collapse weekly activity'} onPress={onCollapseToggle} style={styles.activityToggle}><View style={{transform:[{rotate:collapsed?'0deg':'180deg'}]}}><Icon name="chevron" color={themeColor('#17191d')} size={20}/></View></Pressable></View></View>
  <Animated.View pointerEvents={collapsed?'none':'auto'} style={{height:contentHeight,overflow:'hidden'}}>
  <Animated.View pointerEvents={expanded?'none':'auto'} style={{height:chartHeight,opacity:chartOpacity,overflow:'hidden'}}><View style={styles.activityBars}>{weekMinutes.map((minutes,index)=>{const day=new Date(weekStart);day.setDate(day.getDate()+index);const weekday=(day.getDay()+6)%7;const rest=Object.prototype.hasOwnProperty.call(weeklyPlan,weekday)&&weeklyPlan[weekday]===null;const done=minutes>0;const height=done?Math.max(48,Math.round(34+(minutes/maxMinutes)*82)):rest?116:50;const dayName=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][index];return <Pressable key={index} accessibilityRole="button" accessibilityLabel={`${dayName}, ${planLabel(weekday)}${done?`, ${Math.round(minutes)} minutes`:''}. Tap to change plan.`} onPress={()=>onPlanDay(weekday)} style={styles.activityColumn}><View style={[styles.activityBarTrack,{height,backgroundColor:done?themeColor('#55b9ed','background'):rest?themeColor('#17191d','background'):themeColor('#edf3f7','background')}]}>{!done&&!rest&&<View pointerEvents="none" style={StyleSheet.absoluteFill}>{Array.from({length:7},(_,line)=><View key={line} style={{position:'absolute',width:52,height:1,backgroundColor:themeColor('#c5d3dd','background'),left:-10,top:line*11+7,transform:[{rotate:'-48deg'}]}}/>)}</View>}</View><Text style={styles.activityDay}>{['M','T','W','T','F','S','S'][index]}</Text><Text numberOfLines={1} style={{height:12,lineHeight:12,fontSize:10,fontWeight:'800',color:themeColor('#596875'),width:'100%',textAlign:'center'}}>{done?`${Math.round(minutes)}m`:rest?'0m':''}</Text><Text numberOfLines={1} style={[styles.activityPlanLabel,currentTheme==='dark'&&{color:'#fff'}]}>{planLabel(weekday)}</Text></Pressable>;})}</View></Animated.View>
  <Animated.View pointerEvents={expanded?'auto':'none'} style={{height:calendarHeight,opacity:calendarOpacity,overflow:'hidden'}}><View style={styles.calendarPanel}><View style={styles.calendarMonthHead}><Pressable accessibilityRole="button" accessibilityLabel="Previous month" onPress={()=>onMonthChange(-1)} style={styles.calendarArrow}><Text style={styles.calendarArrowGlyph}>‹</Text></Pressable><Text style={styles.calendarMonthTitle}>{month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</Text><Pressable accessibilityRole="button" accessibilityLabel="Next month" onPress={()=>onMonthChange(1)} style={styles.calendarArrow}><Text style={styles.calendarArrowGlyph}>›</Text></Pressable></View><View style={styles.calendarWeekRow}>{['S','M','T','W','T','F','S'].map((day,index)=><Text key={`${day}-${index}`} style={styles.calendarWeekLabel}>{day}</Text>)}</View>{Array.from({length:6},(_,row)=><View key={row} style={styles.calendarWeekRow}>{monthCells.slice(row*7,row*7+7).map((cell,index)=>cell?<Pressable key={cell.key} accessibilityRole="button" accessibilityLabel={`${month.toLocaleDateString('en-US',{month:'long'})} ${cell.dayNumber}: ${cell.done?'workout completed':cell.rest?'rest day':'not completed'}. Tap to change this weekday plan.`} onPress={()=>onPlanDay(cell.weekday)} style={[styles.calendarCell,cell.done&&styles.calendarDone,cell.rest&&!cell.done&&styles.calendarRest,cell.today&&styles.calendarToday]}><Text style={[styles.calendarDayText,(cell.done||cell.rest)&&styles.calendarLightText]}>{cell.dayNumber}</Text></Pressable>:<View key={`blank-${row}-${index}`} style={styles.calendarCellBlank}/>)}</View>)}<View style={styles.activityLegend}><View style={styles.legendItem}><View style={[styles.legendDot,{backgroundColor:themeColor('#55b9ed','background')}]}/><Text style={styles.legendText}>Done</Text></View><View style={styles.legendItem}><View style={[styles.legendDot,{backgroundColor:themeColor('#f0f2f5','background')}]}/><Text style={styles.legendText}>Not completed</Text></View><View style={styles.legendItem}><View style={[styles.legendDot,{backgroundColor:themeColor('#17191d','background')}]}/><Text style={styles.legendText}>Rest</Text></View></View><Text style={styles.calendarHint}>Tap a date to change its weekday plan</Text></View></Animated.View>
  </Animated.View>
  <View style={{flexDirection:'row',gap:10,marginVertical:6}}><Pressable accessibilityRole="button" accessibilityLabel={todaysPlan?`Start workout ${todaysPlan.name}`:'Assign a split to start'} onPress={onStart} disabled={!todaysPlan} style={[styles.darkButton,{flex:1,minWidth:0,marginVertical:0,paddingHorizontal:13,justifyContent:'center'},!todaysPlan&&{opacity:.5,backgroundColor:themeColor('#33363a','background')}]}><Text style={styles.play}>▶</Text><Text numberOfLines={1} style={[styles.darkButtonText,{fontSize:14,flexShrink:1}]}>{todaysPlan?`Start · ${todaysPlan.name.replace(/\s*\([^)]*\)/g,'').trim()}`:'Start workout'}</Text></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Edit - Today" onPress={onEdit} disabled={!todaysPlan} style={{flex:1,minWidth:0,minHeight:54,borderRadius:30,backgroundColor:themeColor('#f2f4f7','background'),paddingHorizontal:13,flexDirection:'row',alignItems:'center',justifyContent:'center',gap:8,opacity:todaysPlan?1:.5}}><Icon name="edit" color={themeColor('#17191d')} size={17}/><Text numberOfLines={1} style={{fontSize:14,fontWeight:'700',color:themeColor('#17191d'),flexShrink:1}}>Edit - Today</Text></Pressable></View>
 </Animated.View>;
}
function ModalTop({title,onClose,right,onRight}:{title:string;onClose:()=>void;right?:string;onRight?:()=>void}){return <View style={styles.modalTop}><Pressable style={styles.modalClose} onPress={onClose}><Text style={styles.modalCloseText}>×</Text></Pressable><Text style={styles.modalTitle}>{title}</Text>{right?<Pressable onPress={onRight}><Text style={styles.link}>{right}</Text></Pressable>:<View style={{width:40}}/>}</View>}
function Dumbbell(){return <Svg width="54" height="42" viewBox="0 0 54 42"><Path d="M14 21h26" stroke="#28323d" strokeWidth="5" strokeLinecap="round"/><Rect x="5" y="10" width="7" height="22" rx="2" fill="#46515e"/><Rect x="13" y="7" width="6" height="28" rx="2" fill="#68788b"/><Rect x="35" y="7" width="6" height="28" rx="2" fill="#68788b"/><Rect x="42" y="10" width="7" height="22" rx="2" fill="#46515e"/></Svg>}
function ExerciseArt({image,size}:{image?:string;size:'card'|'hero'|'thumb'|'detail'}) {
  if(!image)return null;
  const dimension=size==='detail'?{width:280,height:260}:size==='card'?{width:145,height:138}:size==='hero'?{width:158,height:150}:{width:56,height:48};
  return <ExpoImage source={{uri:datasetAsset(image)}} contentFit="contain" cachePolicy="disk" style={[dimension,{borderRadius:size==='thumb'?12:size==='card'?18:20,overflow:'hidden'}]}/>;
}
function themedStyle(key:PropertyKey,raw:any){if(typeof key!=='string'||!raw||typeof raw!=='object')return raw;const style:any={...StyleSheet.flatten(raw)};const palette=themePalettes[currentTheme];const pageSurface=['root','safe','page','modalScreen','workoutScreen'].includes(key);for(const prop of ['color','backgroundColor','borderColor','borderTopColor','borderBottomColor']){const value=style[prop];if(typeof value!=='string')continue;const hex=value.toLowerCase();if(prop==='color'){if(hex==='#17191d'||hex==='#17181b'||hex==='#252a30'||hex==='#252a2f'||hex==='#28313a')style[prop]=palette.ink;else if(hex==='#9298a1'||hex==='#9299a2'||hex==='#8d949d'||hex==='#9aa1aa'||hex==='#9aa0a7'||hex==='#8e949c'||hex==='#8e959e'||hex==='#989ea6'||hex==='#9199a3'||hex==='#9ba2aa'||hex==='#69727c'||hex==='#707984'||hex==='#7e8791'||hex==='#444c55')style[prop]=palette.muted;else if(hex==='#3478f6')style[prop]=palette.blue;else if(hex==='#fff'&&['darkButtonText','finishText','splitCtaText','splitCtaArrow'].includes(key))style[prop]=palette.buttonText;}else if(prop==='backgroundColor'){if(['darkButton','finishButton','splitCta','createSplitAction'].includes(key))style[prop]=palette.button;else if(pageSurface&&(hex==='#fff'||hex==='#ffffff'))style[prop]=palette.bg;else if(hex==='#fff'||hex==='#ffffff')style[prop]=palette.surface;else if(['#f2f4f7','#f2f5f8','#f3f5f7','#f3f5f7','#f5f6f9','#f7f8fa','#f1f4f7','#f1f2f5','#f2f3f5','#eff0f3','#edf0f4','#edf0f3','#e8ebef'].includes(hex))style[prop]=palette.surfaceAlt;else if(hex==='#17191d'||hex==='#17181b')style[prop]=palette.button;else if(hex==='#d8f0fc')style[prop]=currentTheme==='cyberpunk'?'#efcf28':currentTheme==='dark'?'#1b3346':value;}else if(['#edf0f3','#edf0f4','#e0e6eb','#eef0f3','#e8ebef'].includes(hex))style[prop]=palette.line;}if(currentTheme==='cyberpunk'&&typeof style.fontSize==='number'){style.fontFamily=Platform.select({ios:'Menlo',android:'monospace',web:'monospace'});style.letterSpacing=style.letterSpacing??0.25;}return style;}

function cleanSplitDescription(description?:string){return (description??'').replace(/(?:\s*[·•-]\s*)?Imported from Apple Notes/gi,'').replace(/\s*[·•-]\s*$/,'').trim();}
function SplitCardFace({session}:{session:Session}){
  const title=session.name.replace(/\s*\([^)]*\)/g,'').trim();
  const focus=session.name.match(/\(([^)]+)\)/)?.[1];
  const setCount=session.moves.reduce((count,move)=>count+move.sets.length,0);
  const detail=[focus,cleanSplitDescription(session.description)].filter(Boolean).join(' · ');
  return <><View style={styles.splitCardBody}><View style={styles.splitCardCopy}><View style={{flex:1}}><Text numberOfLines={1} style={[styles.splitName,currentTheme==='dark'&&{color:'#000'}]}>{title}</Text>{detail?<Text numberOfLines={2} style={[styles.splitDesc,currentTheme==='dark'&&{color:'#000'}]}>{detail}</Text>:null}</View></View><View style={[styles.splitArt,{backgroundColor:"#fff"}]}><ExerciseArt image={session.moves[0]?.image} size="card"/></View><View style={styles.splitCardMeta}><Text style={[styles.splitMeta,currentTheme==='dark'&&{color:'#000'}]}>{session.moves.length} {session.moves.length===1?'exercise':'exercises'}  ·  {setCount} {setCount===1?'set':'sets'}</Text></View></View><View style={styles.splitCta}><Text style={styles.splitCtaText}>View split</Text><Text style={styles.splitCtaArrow}>→</Text></View></>;
}

